<?php
require_once __DIR__.'/includes/bootstrap.php'; require_login('siswa'); $user=current_user(); $notice='';
if($_SERVER['REQUEST_METHOD']==='POST'){
  $tugasId=(int)($_POST['tugas_id']??0); $catatan=trim($_POST['catatan']??''); $fileName=null;
  if(!empty($_FILES['berkas']['name']) && $_FILES['berkas']['error']===UPLOAD_ERR_OK){
    $allowed=['pdf','doc','docx','jpg','jpeg','png']; $ext=strtolower(pathinfo($_FILES['berkas']['name'],PATHINFO_EXTENSION));
    if(in_array($ext,$allowed,true) && $_FILES['berkas']['size']<=5*1024*1024){ if(!is_dir(__DIR__.'/uploads')) mkdir(__DIR__.'/uploads',0755,true); $fileName=uniqid('tugas_',true).'.'.$ext; move_uploaded_file($_FILES['berkas']['tmp_name'],__DIR__.'/uploads/'.$fileName); } else $notice='Berkas harus PDF, DOCX, JPG, atau PNG (maks. 5 MB).';
  }
  if(!$notice && ($catatan!=='' || $fileName)){ $stmt=$pdo->prepare("INSERT INTO pengumpulan_tugas (tugas_id,user_id,catatan,nama_file) VALUES (?,?,?,?) ON DUPLICATE KEY UPDATE catatan=VALUES(catatan), nama_file=COALESCE(VALUES(nama_file),nama_file), submitted_at=CURRENT_TIMESTAMP"); $stmt->execute([$tugasId,$user['id'],$catatan,$fileName]); $notice='Tugas berhasil dikumpulkan.'; }
}
$tasks=$pdo->prepare("SELECT t.*,p.id AS kiriman_id,p.catatan,p.nama_file,p.nilai,p.komentar_guru,p.submitted_at FROM tugas t LEFT JOIN pengumpulan_tugas p ON p.tugas_id=t.id AND p.user_id=? ORDER BY t.tenggat IS NULL,t.tenggat"); $tasks->execute([$user['id']]); $tasks=$tasks->fetchAll();
$activeTab='tugas'; $pageTitle='Tugas'; require __DIR__.'/includes/header.php'; require __DIR__.'/includes/sidebar_siswa.php'; ?>
<div class="dash-head"><div><h2>Ruang tugas 📤</h2><p>Kumpulkan jawabanmu dan lihat masukan dari guru di sini.</p></div></div><?php if($notice): ?><div class="auth-success"><?= h($notice) ?></div><?php endif; ?>
<?php foreach($tasks as $t): ?><section class="task-card"><div class="task-title"><div><span class="video-tag"><?= $t['tenggat']?'TENGGAT: '.date('d M Y',strtotime($t['tenggat'])):'TANPA TENGGAT' ?></span><h3><?= h($t['judul']) ?></h3></div><span class="task-status <?= $t['kiriman_id']?'done':'' ?>"><?= $t['kiriman_id']?'Terkumpul':'Belum dikumpulkan' ?></span></div><p><?= nl2br(h($t['instruksi'])) ?></p><?php if($t['kiriman_id']): ?><div class="submission-note">✅ Dikumpulkan <?= h($t['submitted_at']) ?><?= $t['nilai']!==null?' · Nilai: <b>'.(int)$t['nilai'].'</b>':'' ?><?= $t['komentar_guru']?'<br>💬 Guru: '.h($t['komentar_guru']):'' ?></div><?php endif; ?><form method="post" enctype="multipart/form-data" class="task-form"><input type="hidden" name="tugas_id" value="<?= $t['id'] ?>"><textarea name="catatan" placeholder="Tulis jawaban atau catatan untuk guru..."><?= h($t['catatan']??'') ?></textarea><label class="file-label">📎 Lampiran (PDF/DOCX/JPG/PNG, maks 5MB)<input type="file" name="berkas" accept=".pdf,.doc,.docx,.jpg,.jpeg,.png"></label><button class="btn btn-primary btn-sm"><?= $t['kiriman_id']?'Perbarui kiriman':'Kumpulkan tugas' ?></button></form></section><?php endforeach; if(!$tasks): ?><div class="panel"><h3>Belum ada tugas</h3><p>Guru akan menambahkan tugas di sini.</p></div><?php endif; ?></div></div><?php require __DIR__.'/includes/footer.php'; ?>
